use vstd::prelude::*;

verus! {

fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    ensures
        b@ == a@,
{
    let mut b: Vec<u64> = Vec::with_capacity(a.len());

    for &x in a.iter()
        invariant
            b@ == a@.subrange(0, b@.len() as int),
            b@.len() <= a@.len(),
    {
        // `x` is the next element of `a`'s iterator; pushing it extends `b`
        // to match a longer prefix of `a`.
        b.push(x);
    }

    b
}

} // verus!

